-- Retail Accounts: target DDL generated by SpecSmith from the feed spec.
-- ANSI SQL; adjust types for your warehouse. Columns marked TBD still need a decision.

CREATE SCHEMA IF NOT EXISTS raw;
CREATE SCHEMA IF NOT EXISTS curated;
CREATE SCHEMA IF NOT EXISTS analytics;

-- ======================================================================
-- accounts (source file accounts.csv, 13 columns)
-- Types: account_id=string(20), customer_id=string(20), account_type_code=string(5), open_date=date [YYYY-MM-DD], close_date=date [YYYY-MM-DD], status_code=string(20), branch_number=string(10), currency_code=string(5), credit_limit_amount=decimal(9,2), current_balance_amount=decimal(9,2), interest_rate=decimal(6,4), overdraft_flag=boolean, last_statement_date=date [YYYY-MM-DD]
CREATE TABLE raw.accounts (
  "acct_id" VARCHAR(16),
  "cust_id" VARCHAR(14),
  "acct_type_cd" VARCHAR(6),
  "open_dt" VARCHAR(20),
  "close_dt" VARCHAR(20),
  "status_cd" VARCHAR(14),
  "branch_no" VARCHAR(10),
  "currency_cd" VARCHAR(6),
  "credit_limit_amt" VARCHAR(16),
  "current_bal_amt" VARCHAR(16),
  "interest_rate" VARCHAR(12),
  "overdraft_flag" VARCHAR(2),
  "last_stmt_dt" VARCHAR(20)
);

CREATE TABLE curated.accounts (
  account_id VARCHAR(20) NOT NULL,
  customer_id VARCHAR(20) NOT NULL,
  account_type_code VARCHAR(5) NOT NULL,
  open_date DATE NOT NULL,
  close_date DATE,
  status_code VARCHAR(20) NOT NULL,
  branch_number VARCHAR(10) NOT NULL,
  currency_code VARCHAR(5) NOT NULL,
  credit_limit_amount DECIMAL(9,2),
  current_balance_amount DECIMAL(9,2) NOT NULL,
  interest_rate DECIMAL(6,4) NOT NULL,
  overdraft_flag BOOLEAN NOT NULL,
  last_statement_date DATE NOT NULL,
  CONSTRAINT pk_accounts PRIMARY KEY (account_id)
);

CREATE VIEW analytics.accounts AS
SELECT
  account_id,
  customer_id,
  account_type_code,
  open_date,
  close_date,
  status_code,
  branch_number,
  currency_code,
  credit_limit_amount,
  current_balance_amount,
  interest_rate,
  overdraft_flag,
  last_statement_date
FROM curated.accounts;
-- ======================================================================
-- cards (source file cards.csv, 9 columns)
-- Types: card_id=string(20), account_id=string(20), card_number=string(30), cardholder_name=string(30), expiry_mm_yy=string(10), cvv=string(5), card_status=string(20), issue_date=date [YYYY-MM-DD], contactless_indicator=boolean
CREATE TABLE raw.cards (
  "card_id" VARCHAR(16),
  "acct_id" VARCHAR(16),
  "card_no" VARCHAR(32),
  "cardholder_nm" VARCHAR(30),
  "exp_mm_yy" VARCHAR(10),
  "cvv" VARCHAR(6),
  "card_status" VARCHAR(14),
  "issue_dt" VARCHAR(20),
  "contactless_ind" VARCHAR(10)
);

CREATE TABLE curated.cards (
  card_id VARCHAR(20) NOT NULL,
  account_id VARCHAR(20) NOT NULL,
  card_number VARCHAR(30) NOT NULL,
  cardholder_name VARCHAR(30) NOT NULL,
  expiry_mm_yy VARCHAR(10) NOT NULL,
  cvv VARCHAR(5) NOT NULL,
  card_status VARCHAR(20) NOT NULL,
  issue_date DATE NOT NULL,
  contactless_indicator BOOLEAN NOT NULL,
  CONSTRAINT pk_cards PRIMARY KEY (card_id)
);

-- Left out until a masking policy is approved: card_number (PCI card_number), cardholder_name (PCI cardholder_name), expiry_mm_yy (PCI card_expiry), cvv (PCI card_security_code)
CREATE VIEW analytics.cards AS
SELECT
  card_id,
  account_id,
  card_status,
  issue_date,
  contactless_indicator
FROM curated.cards;
-- ======================================================================
-- customers (source file customers.csv, 18 columns)
-- Types: customer_id=string(20), first_name=string(10), last_name=string(20), c_email=string(50), phone_number=string(30), dob=date [YYYY-MM-DD], c_sin=string(20), address_line1=string(30), city=string(20), province_code=string(3), postal_code=string(20), customer_since_date=date [YYYY-MM-DD], segment_code=string(20), kyc_status=string(20), flag_x=boolean, col_17=string(10), marketing_opt_in=bool
CREATE TABLE raw.customers (
  "cust_id" VARCHAR(14),
  "first_nm" VARCHAR(12),
  "last_nm" VARCHAR(16),
  "c_email" VARCHAR(60),
  "phone_no" VARCHAR(28),
  "dob" VARCHAR(20),
  "c_sin" VARCHAR(22),
  "addr_line1" VARCHAR(34),
  "city" VARCHAR(18),
  "prov_cd" VARCHAR(4),
  "postal_cd" VARCHAR(14),
  "cust_since_dt" VARCHAR(20),
  "segment_cd" VARCHAR(14),
  "kyc_status" VARCHAR(16),
  "FLAG_X" VARCHAR(2),
  "col_17" VARCHAR(12),
  "marketing_opt_in" VARCHAR(10),
  "created_ts" VARCHAR(38)
);

CREATE TABLE curated.customers (
  customer_id VARCHAR(20) NOT NULL,
  first_name VARCHAR(10) NOT NULL,
  last_name VARCHAR(20) NOT NULL,
  c_email VARCHAR(50),
  phone_number VARCHAR(30),
  dob DATE NOT NULL,
  c_sin VARCHAR(20) NOT NULL,
  address_line1 VARCHAR(30) NOT NULL,
  city VARCHAR(20) NOT NULL,
  province_code VARCHAR(3) NOT NULL,
  postal_code VARCHAR(20) NOT NULL,
  customer_since_date DATE NOT NULL,
  segment_code VARCHAR(20) NOT NULL,
  kyc_status VARCHAR(20),
  flag_x BOOLEAN NOT NULL,
  col_17 VARCHAR(10),
  marketing_opt_in BOOLEAN NOT NULL,
  created_timestamp TIMESTAMP NOT NULL,
  CONSTRAINT pk_customers PRIMARY KEY (customer_id)
);

-- Left out until a masking policy is approved: first_name (PII person_name), last_name (PII person_name), c_email (PII email), phone_number (PII phone), dob (PII date_of_birth), c_sin (PII government_id), address_line1 (PII address), postal_code (PII postal_code)
CREATE VIEW analytics.customers AS
SELECT
  customer_id,
  city,
  province_code,
  customer_since_date,
  segment_code,
  kyc_status,
  flag_x,
  col_17,
  marketing_opt_in,
  created_timestamp
FROM curated.customers;
-- ======================================================================
-- transactions (source file transactions.csv, 13 columns)
-- Types: transaction_id=integer, account_id=string(20), transaction_timestamp=timestamp [ISO-8601 timestamp], posting_date=date [DD/MM/YYYY], transaction_amount=decimal(8,2), transaction_type_code=string(20), channel_code=string(10), merchant_name=string(30), merchant_category_code=integer, description_text=string(100), ip_address=string(30), device_id=string(100), reversal_flag=boolean
CREATE TABLE raw.transactions (
  "txn_id" VARCHAR(20),
  "acct_id" VARCHAR(16),
  "txn_ts" VARCHAR(38),
  "posting_dt" VARCHAR(20),
  "txn_amt" VARCHAR(14),
  "txn_type_cd" VARCHAR(16),
  "channel_cd" VARCHAR(12),
  "merchant_nm" VARCHAR(28),
  "merchant_category_cd" VARCHAR(8),
  "description_txt" VARCHAR(124),
  "ip_addr" VARCHAR(30),
  "device_id" VARCHAR(72),
  "reversal_flag" VARCHAR(2)
);

CREATE TABLE curated.transactions (
  transaction_id BIGINT NOT NULL,
  account_id VARCHAR(20) NOT NULL,
  transaction_timestamp TIMESTAMP NOT NULL,
  posting_date DATE NOT NULL,
  transaction_amount DECIMAL(8,2) NOT NULL,
  transaction_type_code VARCHAR(20) NOT NULL,
  channel_code VARCHAR(10) NOT NULL,
  merchant_name VARCHAR(30) NOT NULL,
  merchant_category_code BIGINT NOT NULL,
  description_text VARCHAR(100),
  ip_address VARCHAR(30),
  device_id VARCHAR(100),
  reversal_flag BOOLEAN NOT NULL,
  CONSTRAINT pk_transactions PRIMARY KEY (transaction_id)
);

-- Left out until a masking policy is approved: ip_address (PII ip_address), device_id (PII device_id)
CREATE VIEW analytics.transactions AS
SELECT
  transaction_id,
  account_id,
  transaction_timestamp,
  posting_date,
  transaction_amount,
  transaction_type_code,
  channel_code,
  merchant_name,
  merchant_category_code,
  description_text,
  reversal_flag
FROM curated.transactions;
